'use strict';
const storageKey=new URLSearchParams(location.search).has('qa')?'kyn-qa-v2':'kyn-v2';
const M=WalkModel,$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state;try{state=JSON.parse(localStorage.getItem(storageKey));if(state?.version!==2)state=M.seed()}catch{state=M.seed()}
let view='book',step='plan',filter='all',zoom=1,focusReturn=null,searchTimer,toastTimer,draft={from:'union',to:'',service:'walk',when:'now',date:'',notes:''};
const icons={walk:'M13 4a2 2 0 1 0 0 .1M10 9l4-1 3 4 3 1M14 8l-2 7 4 5M12 15l-4 6M10 9l-3 5-3 1',arrow:'M5 12h14m-5-5 5 5-5 5',back:'M19 12H5m5-5-5 5 5 5',chevron:'m9 6 6 6-6 6',down:'m6 9 6 6 6-6',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0ZM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',calendar:'M4 5h16v16H4ZM4 10h16M8 2v6m8-6v6',home:'m3 11 9-8 9 8M5 10v11h14V10M9 21v-7h6v7',work:'M3 7h18v14H3ZM8 7V3h8v4M3 12h18M10 12v3h4v-3',train:'M7 3h10q3 0 3 3v11q0 3-3 3H7q-3 0-3-3V6q0-3 3-3ZM4 12h16M12 3v9M7 16h1m8 0h1M8 20l-2 3m10-3 2 3',shield:'m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6ZM8 12l3 3 5-6',check:'m5 12 4 4L19 6',close:'m6 6 12 12M18 6 6 18',swap:'M8 3v18m-4-4 4 4 4-4M16 21V3m-4 4 4-4 4 4',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M4 22v-3a8 8 0 0 1 16 0v3',users:'M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M2 22v-4a7 7 0 0 1 14 0v4M17 4a4 4 0 0 1 0 8m1 3a6 6 0 0 1 4 6',chat:'M21 4H3v14h5l4 4v-4h9ZM7 9h10M7 13h6',phone:'M7 3H3c-2 10 8 20 18 18v-4l-5-2-2 3c-4-1-7-4-8-8l3-2Z',plus:'M12 5v14M5 12h14',minus:'M5 12h14',locate:'M12 1v4m0 14v4M1 12h4m14 0h4M19 12a7 7 0 1 1-14 0 7 7 0 0 1 14 0M14 12a2 2 0 1 1-4 0 2 2 0 0 1 4 0',info:'M12 11v6M12 7h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',credit:'M3 4h18v16H3ZM3 9h18M6 16h4',download:'M12 2v13m-5-5 5 5 5-5M3 17v5h18v-5',share:'M12 16V2m-5 5 5-5 5 5M6 9H3v13h18V9h-3',star:'m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1Z',heart:'M12 21S1 14 2 7c1-6 8-6 10-1 2-5 9-5 10 1 1 7-10 14-10 14',receipt:'M5 2l3 2 4-2 4 2 3-2v20l-3-2-4 2-4-2-3 2ZM8 8h8M8 12h8M8 16h4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 2h6l1 4 4 1 2 5-3 3v4l-5 3-3-3-4 1-4-4 1-4-2-3 3-5Z',bolt:'m14 2-10 12h7l-1 8 10-12h-7Z',flag:'M4 22V3m0 0h15l-3 5 3 5H4',bell:'M5 16V9a7 7 0 0 1 14 0v7l2 3H3ZM9 22h6',moon:'M20 15A9 9 0 0 1 9 3 9 9 0 1 0 20 15',lock:'M5 10h14v12H5ZM8 10V6a4 4 0 1 1 8 0v4',play:'m7 3 15 9-15 9Z',refresh:'M20 7A9 9 0 1 0 21 15M20 2v6h-6',globe:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0M2 12h20M12 2c-6 5-6 15 0 20 6-5 6-15 0-20'};
const I=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.info}"/></svg>`;
const B=(label,action,cls='primary',extra='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;
const P=id=>M.getPlace(id),money=M.money,active=()=>state.trips.find(t=>!M.terminal.includes(t.status)),current=()=>state.trips.find(t=>t.id===state.currentId)||active();
const fmtDate=(d,short=false)=>new Date(d).toLocaleDateString('en-US',{month:'short',day:'numeric',...(short?{}:{weekday:'short'})});
const fmtTime=d=>new Date(d).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'});
const firstName=()=>state.user.name.split(' ')[0]||'Alex';
const serviceName=s=>s==='subway'?'Subway Together':'Walk Home';
function persist(){try{localStorage.setItem(storageKey,JSON.stringify(state))}catch{toast('Storage is unavailable. Changes will last for this session only.')}}
function toast(s){clearTimeout(toastTimer);$('#toast').textContent=s;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000)}
function closeModal(){$('#modal').close();if(focusReturn?.isConnected)focusReturn.focus()}
function modal(title,body){focusReturn=document.activeElement;$('#modal-body').innerHTML=`<div class="modal-header"><h2 id="modal-title">${title}</h2><button class="close-btn" data-action="close" aria-label="Close dialog">${I('close')}</button></div><div class="modal-content">${body}</div>`;if(!$('#modal').open)$('#modal').showModal()}
function alertError(err){toast(err.message||err)}
function header(){return `<header class="topbar"><a href="#book" class="brand" data-action="nav" data-view="book"><span class="brand-mark">${I('walk')}</span>kyn<small>NYC</small></a><nav class="topnav" aria-label="Main navigation">${[['book','Book a journey'],['activity','Activity'],['help','Help']].map(([v,n])=>`<button data-action="nav" data-view="${v}" data-nav="${v}" class="${view===v?'current':''}">${n}</button>`).join('')}</nav><div class="topright"><span class="region">${I('pin')} New York City</span><button class="demo-badge" data-action="demo">INTERACTIVE DEMO</button><button class="account-btn" data-action="nav" data-view="account" aria-label="Open account"><span class="avatar">${esc(state.user.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span><span>${esc(firstName())}</span>${I('down')}</button></div></header>`}
function routeSummary(from=draft.from,to=draft.to){return `<div class="route-summary"><div class="route-line"><span class="input-dot"></span><span>${esc(P(from)?.name||'Choose a meeting point')}<small>${esc(P(from)?.address||'')}</small></span></div><div class="route-connector"></div><div class="route-line"><span class="input-dot destination"></span><span>${esc(P(to)?.name||'Choose a destination')}<small>${esc(P(to)?.address||'')}</small></span></div></div>`}
function mapMarkup(){const t=current(),a=P(view==='book'&&step==='trip'&&t?t.from:draft.from),b=P(view==='book'&&step==='trip'&&t?t.to:draft.to);let blocks='',roads='',labels='';
for(let row=-2;row<14;row++)for(let col=-2;col<10;col++){const x=col*108,y=row*61;blocks+=`<rect x="${x+7}" y="${y+8}" width="91" height="44" rx="2" fill="${(row+col)%4===0?'#dfe4da':'#e3e7df'}" stroke="#d5dccf" stroke-width=".7"/>`;if((row+col)%3===0)blocks+=`<path d="M${x+30} ${y+8}v44m30-44v44" stroke="#d4dccd" stroke-width=".6"/>`}
for(let row=-1;row<14;row++){roads+=`<path d="M-250 ${row*61}H1250" stroke="#fbfcf7" stroke-width="11"/>`;if(row>0&&row<11)labels+=`<text x="720" y="${row*61+3}" font-size="9" fill="#9aa38e">E ${20-row}TH STREET</text>`}
for(let col=0;col<10;col++)roads+=`<path d="M${col*108} -200V1100" stroke="#fbfcf7" stroke-width="15"/>`;
const path=a&&b?`M${a.x} ${a.y} L${a.x+22} ${a.y+38} L${b.x+22} ${b.y-32} L${b.x} ${b.y}`:'';
const q=a&&b?M.quote(a.id,b.id,(t&&step==='trip'?t.service:draft.service)):null;
let pin=(p,label,type)=>`<g transform="translate(${p.x},${p.y})"><circle r="16" fill="#fff" stroke="#263d2c" stroke-width="3"/><${type==='start'?'circle r="5"':'rect x="-5" y="-5" width="10" height="10"'} fill="#263d2c"/><g transform="translate(22,-14)"><rect width="${Math.min(190,label.length*6.2+24)}" height="29" rx="5" fill="#203b2b"/><text x="12" y="19" fill="white" font-size="11" font-weight="600">${esc(label)}</text></g></g>`;
return `<div class="map-side ${step==='trip'?'trip-map':''}"><div class="map-canvas" style="transform:scale(${zoom})"><svg viewBox="100 70 900 680" preserveAspectRatio="xMidYMid slice" role="img" aria-label="Illustrative map of the East Village and Greenwich Village, showing your selected meeting points"><defs><pattern id="parkdots" width="17" height="17" patternUnits="userSpaceOnUse"><circle cx="5" cy="5" r="1.5" fill="#b7caa2"/></pattern></defs><rect width="1200" height="900" fill="#edf0e7"/><g transform="rotate(-28 500 400)">${blocks}${roads}${labels}<text x="218" y="580" transform="rotate(-90 218 580)" font-size="10" fill="#99a28f">FIFTH AVENUE</text><text x="546" y="480" transform="rotate(-90 546 480)" font-size="10" fill="#99a28f">THIRD AVENUE</text><text x="870" y="480" transform="rotate(-90 870 480)" font-size="10" fill="#99a28f">AVENUE A</text></g><path d="M330 800Q345 590 470 360T570 0" fill="none" stroke="#d6ddcc" stroke-width="22"/><path d="M330 800Q345 590 470 360T570 0" fill="none" stroke="#fafbf6" stroke-width="17"/><text x="443" y="422" transform="rotate(-65 443 422)" fill="#a0a890" font-size="9" letter-spacing="2">BROADWAY</text><path d="M448 168 533 155 558 222 500 257 453 240Z" fill="#cbdcba" stroke="#b6cca0"/><path d="M460 173 500 240m32-72-69 60" stroke="#e4edd9" stroke-width="4"/><text x="498" y="200" text-anchor="middle" fill="#7c9366" font-size="9">UNION</text><text x="498" y="213" text-anchor="middle" fill="#7c9366" font-size="9">SQUARE</text><path d="M220 510H355V600H220Z" fill="#cbdcba" stroke="#b6cca0"/><path d="M220 555H355M287 510V600" stroke="#e9f0df" stroke-width="7"/><circle cx="287" cy="555" r="22" fill="#dce8cd" stroke="#c2d4af" stroke-width="3"/><circle cx="287" cy="555" r="8" fill="#c3d6d4"/><text x="286" y="584" text-anchor="middle" fill="#7a9162" font-size="8">WASHINGTON SQUARE PARK</text><path d="M795 395h136v108H795z" fill="#cbdcba" stroke="#b6cca0"/><path d="m802 403 121 91m0-91-121 91" stroke="#e8efdc" stroke-width="5"/><text x="864" y="443" text-anchor="middle" fill="#78905e" font-size="9">TOMPKINS</text><text x="864" y="456" text-anchor="middle" fill="#78905e" font-size="9">SQUARE PARK</text><rect x="710" y="163" width="54" height="54" rx="5" fill="#cbdcba"/><g fill="#909a84" font-size="13" font-family="Arial" letter-spacing="3" opacity=".7"><text x="633" y="354">EAST VILLAGE</text><text x="135" y="430">GREENWICH</text><text x="165" y="448">VILLAGE</text><text x="626" y="110">GRAMERCY</text><text x="390" y="686">NOHO</text></g><g font-family="Arial" font-size="9" fill="#879879"><text x="385" y="616">NEW YORK UNIVERSITY</text><text x="635" y="480">COOPER UNION</text><text x="587" y="405">ASTOR PLACE</text></g><path d="M195 360Q240 120 560 110L950 300 945 570 460 685 190 640Z" stroke="#9bb78a" stroke-dasharray="4 5" stroke-width="1.1" fill="none" opacity=".7"/>${path?`<path d="${path}" stroke="#fff" stroke-width="9" fill="none" stroke-linejoin="round"/><path d="${path}" stroke="#36513b" stroke-width="5" fill="none" stroke-linejoin="round"/>`:''}${a?pin(a,a.name,'start'):''}${b?pin(b,b.name,'end'):''}${t&&step==='trip'&&['assigned','arrived','active','awaiting_end'].includes(t.status)?`<g transform="translate(${a.x+(b.x-a.x)*(t.status==='active'?(t.milestone||0)/3:0)-30},${a.y+(b.y-a.y)*(t.status==='active'?(t.milestone||0)/3:0)-40})"><circle r="20" fill="#ddecad" stroke="#fff" stroke-width="4"/><text y="4" text-anchor="middle" fill="#34492b" font-size="11" font-weight="700">JL</text></g>`:''}</svg></div><div class="map-top"><div class="map-pill">${I('pin')} East Village & NYU <span class="status-dot"></span></div><button class="map-pill" data-action="coverage">Pilot area ${I('info')}</button></div>${q?`<div class="map-route-card"><b>${q.minutes} min</b> ${(step==='trip'&&t?t.service:draft.service)==='subway'?'together':'walk'}<small>${q.miles} mi · Sample route</small></div>`:`<div class="map-story"><div class="mini-people"><span>JL</span><span>SK</span><span>MR</span></div><div class="eyebrow">COMPANY FOR THE WAY THERE</div><h3>A new route.<br>A familiar feeling.</h3><p>Walking home or catching the train?<br>There’s a buddy for that.</p></div>`}<div class="map-controls"><button data-action="zoom-in" aria-label="Zoom in">${I('plus')}</button><button data-action="zoom-out" aria-label="Zoom out">${I('minus')}</button><button data-action="recenter" aria-label="Recenter map">${I('locate')}</button></div><span class="map-attribution">KYN · Illustrative map · Not live navigation</span></div>`}
function dock(){const t=current();let next='';if(view==='book'&&step==='trip'&&t){const labels={searching:'Find companion',assigned:'Companion arrives',arrived:'Show meeting PIN',active:t.milestone>=3?'Confirm arrival':'Next checkpoint',awaiting_end:'Companion confirms',review:'Resolve completion'};if(labels[t.status])next=`<span class="divider"></span><button class="advance" data-action="advance">${labels[t.status]} →</button>`}return `<div class="demo-dock"><span>${I('play')}</span><button data-action="demo">Demo controls</button>${next}<span class="divider"></span><button data-action="restart" aria-label="Start a new demo">${I('refresh')}</button></div>`}
function plan(){return `<div class="location-kicker"><span class="status-dot"></span> NEW YORK CITY <span> / </span> EAST VILLAGE PILOT</div><h1>Where are we headed?</h1><p class="subheading">A little company for your next journey.</p><div class="service-tabs" role="group" aria-label="Journey type">${[['walk','walk','Walk'],['subway','train','Subway'],['free','users','Find a match']].map(([id,i,label])=>`<button data-action="service" data-service="${id}" class="${draft.service===id?'active':''}" aria-pressed="${draft.service===id}">${I(i)} ${label}</button>`).join('')}</div>${draft.service==='free'?freePanel():`<form id="planner" autocomplete="off"><div class="route-form">${['from','to'].map((field,i)=>`<div class="input-wrap"><div class="input-shell"><span class="input-dot ${i?'destination':''}"></span><div><label for="${field}">${i?'DESTINATION':'MEET ME AT'}</label><input id="${field}" name="${field}" data-location="${field}" value="${esc(P(draft[field])?.name||'')}" placeholder="${i?'Where to?':'Search a public place'}" autocomplete="off" aria-autocomplete="list" aria-controls="suggest-${field}"></div><button type="button" data-action="clear-place" data-field="${field}" aria-label="Clear ${i?'destination':'meeting point'}">${I('close')}</button></div><div class="suggestions" id="suggest-${field}" hidden></div></div>`).join('')}<button type="button" class="swap-btn" data-action="swap" aria-label="Swap meeting point and destination">${I('swap')}</button></div><button type="button" class="schedule-button" data-action="schedule">${I(draft.when==='now'?'clock':'calendar')}<span>${scheduleLabel()}<small>${draft.when==='now'?'On-demand preview':'Scheduled journey'}</small></span>${I('down')}</button><p class="inline-error" id="plan-error" aria-live="polite"></p><button class="btn primary full" type="submit">See available journeys ${I('arrow')}</button></form><p class="microcopy">${I('lock').replace('class="icon"','class="icon" style="width:10px;height:10px;vertical-align:middle"')} Your exact home address can stay private.</p><div class="separator"></div><div class="section-label">Saved places <button data-action="saved">Manage</button></div><div class="saved-places"><button class="place-chip" data-action="saved-go" data-place="home">${I('home')} Home</button><button class="place-chip" data-action="saved-go" data-place="work">${I('work')} Campus</button><button class="place-chip" data-action="saved" aria-label="Add a saved place">${I('plus')}</button></div><div class="section-label" style="margin-top:27px">Around your neighborhood</div>${['washington','astor','tompkins'].map(id=>`<button class="recent-place" data-action="choose-place" data-field="to" data-place="${id}"><span class="icon-box">${I(id==='astor'?'train':'pin')}</span><span><strong>${P(id).name}</strong><small>${P(id).address}</small></span>${I('chevron')}</button>`).join('')}`}`}
function scheduleLabel(){return draft.when==='now'?'Leave now':`${fmtDate(draft.date,true)}, ${fmtTime(draft.date)}`}
function freePanel(){return `<div class="info-note">${I('users')}KYN Together connects people already heading the same way. Both people choose whether to meet.</div><h3>Your next shared walk starts here.</h3><p class="subheading">The free matching pilot is opening in small groups. Join the local demo waitlist to see what enrollment feels like.</p><form id="free-form"><label class="form-label">Your neighborhood<select name="area"><option>East Village</option><option>Greenwich Village</option><option>Union Square</option></select></label><label class="check-label"><input type="checkbox" required>I'm 18 or older and want to opt into the free pilot.</label><button class="btn primary full">${state.freeInterest?'Update my interest':'Join the pilot waitlist'}</button></form><p class="microcopy">Saved on this device. No enrollment is sent to a live service.</p>`}
function transitItinerary(from=draft.from,to=draft.to){const direct=(from==='union'&&to==='astor')||(from==='astor'&&to==='union');return `<button class="selection-row" data-action="itinerary"><span class="subway-bullet">6</span><span><h3>${direct?'One stop, with a local beside you':'Your subway journey plan'}</h3><p>${direct?(from==='union'?'Downtown':'Uptown')+' 6 · '+P(from).name+' → '+P(to).name:'Companion route review before departure'}</p></span>${I('chevron')}</button>`}
function options(){const q=M.quote(draft.from,draft.to,draft.service);return `<button class="back" data-action="back-plan">${I('back')} Edit journey</button><div class="eyebrow">STEP 1 OF 2</div><h1>Choose your company.</h1><p class="subheading">One companion. With you the whole way.</p>${routeSummary()}${['walk','subway'].map(s=>{const x=M.quote(draft.from,draft.to,s);return `<button class="service-card ${draft.service===s?'selected':''}" data-action="option" data-service="${s}"><span class="service-art">${I(s==='walk'?'walk':'train')}</span><span><h3>${serviceName(s)}</h3><p>${s==='walk'?'Doorstep conversation, at your pace.':'Platforms, transfers, and the right exit.'}</p><p style="margin-top:7px;color:#4b6140">${x.minutes} min · ${s==='walk'?x.miles+' mi':'Human-guided journey'}</p></span><span class="price">${money(x.total)}<small>total estimate</small></span></button>`}).join('')}<div class="info-note">${I('shield')}All companion profiles in this demo are fictional. Screening and training badges show the intended experience.</div><button class="schedule-button" data-action="schedule">${I('calendar')}<span>${scheduleLabel()}</span>${I('chevron')}</button>${B('Continue with '+serviceName(draft.service)+' '+I('arrow'),'review','primary full')}<p class="microcopy">Upfront estimate. No extra charges without your approval.</p>${draft.service==='subway'?`${transitItinerary()}<p class="microcopy">Subway fare is paid separately by each person.</p>`:''}`}
function review(){const q=M.quote(draft.from,draft.to,draft.service),pay=state.wallet.find(w=>w.id===state.payment);return `<button class="back" data-action="back-options">${I('back')} Choose service</button><div class="eyebrow">STEP 2 OF 2</div><h1>Make it a plan.</h1><p class="subheading">A few details, then you’re on your way.</p><div class="detail-row"><div>${I(draft.service==='walk'?'walk':'train')}<b>${serviceName(draft.service)}</b></div><span>${q.minutes} min</span></div>${routeSummary()}${draft.service==='subway'?transitItinerary():''}<div class="detail-row"><div>${I('calendar')}<span>${scheduleLabel()}</span></div><button data-action="schedule">Edit</button></div><div class="detail-row"><div>${I('pin')}<span>Public meeting point<small>${esc(P(draft.from).meet)}</small></span></div></div><div class="detail-row"><div><span class="card-number">${pay.name==='Visa'?'VISA':'MC'}</span><span>${pay.name} •••• ${pay.last4}<small>Test payment method</small></span></div><button data-action="payment">Change</button></div><div class="detail-row"><div>${I('chat')}<span>Note for your buddy<small>${esc(draft.notes||state.user.notes||'Anything that would make your walk better?')}</small></span></div><button data-action="notes">${draft.notes?'Edit':'Add'}</button></div><div class="total-row"><span>Total estimate<button data-action="fare" aria-label="Show fare breakdown" style="vertical-align:middle;margin-left:5px">${I('info')}</button></span><b>${money(q.total)}</b></div>${state.user.ageConfirmed?'':`<label class="check-label"><input type="checkbox" id="adult">I’m 18 or older. I understand KYN offers companionship, not security or emergency response.</label>`}<p class="inline-error" id="review-error" aria-live="polite"></p>${B('Confirm '+serviceName(draft.service)+' '+I('arrow'),'request','primary full')}<p class="microcopy">Demo booking · No real payment or dispatch.<br><button data-action="cancellation-policy" style="text-decoration:underline;font-size:10px">Cancellation policy</button></p>`}
function companion(){return `<div class="companion-card"><div class="companion-head"><span class="avatar big person">JL</span><div><h3>Jamie L.</h3><p>Your neighborhood companion</p></div><div class="rating">★ 4.96<small>128 journeys</small></div></div><div class="companion-meta"><span class="pill">${I('shield')} Screened</span><span class="pill">${I('check')} Trained</span><span class="pill">English · Spanish</span></div><p class="companion-bio">“NYU alum, neighborhood regular, and always happy to take the scenic way.”</p><div class="companion-actions">${B(I('chat')+' Message','chat','secondary')}${B(I('user')+' Profile','companion-profile','outline')}</div></div>`}
function tripView(){const t=current();if(!t){step='plan';return plan()}const q=t.quote;if(t.status==='searching')return `<div class="eyebrow">FINDING YOUR BUDDY</div><h1>Good company is<br>on the way.</h1><p class="subheading">Checking companions for your journey.</p><div class="pulse">${I('walk')}</div><div class="center"><span class="spinner"></span><p style="font-size:12px;margin-top:12px">Looking for your neighborhood match…</p></div>${routeSummary(t.from,t.to)}<div class="detail-row"><span>${serviceName(t.service)}</span><b>${money(q.total)}</b></div><p class="microcopy">Matching is simulated in this demo. You can also advance it with Demo controls.</p>${B('Cancel request','cancel','text full')}`;
if(t.status==='unavailable')return `<div class="success-icon" style="background:#f0f2e8">${I('users')}</div><h1>No buddy available<br>for this journey.</h1><p class="subheading">Try a later departure. Your payment method hasn’t been charged.</p>${routeSummary(t.from,t.to)}${B('Try another time','retry','primary full')}${B('Back to booking','new-journey','text full')}`;
if(t.status==='cancelled')return `<div class="success-icon" style="background:#f0f2e8">${I('check')}</div><h1>Your journey is cancelled.</h1><p class="subheading">No payment was taken. We’ll be here when you’re ready.</p>${routeSummary(t.from,t.to)}${B('Plan another journey','new-journey','primary full')}${B('View activity','nav','text full','data-view="activity"')}`;
if(t.status==='reported')return `<div class="success-icon" style="background:#f7e7e2">${I('shield')}</div><h1>Your journey has ended.</h1><p class="subheading">Your report is saved in this demo. Location sharing is off.</p><div class="info-note">${I('info')}There is no live support team in this demo. In immediate danger, contact emergency services directly.</div>${B('View report','report-status','primary full')}${B('Back to booking','new-journey','text full')}`;
if(t.status==='completed')return completed(t);
if(t.status==='review')return `<h1>Completion under review.</h1><p class="subheading">The two participants did not confirm the same outcome. No additional amount has been charged.</p>${routeSummary(t.from,t.to)}<div class="info-note">${I('info')}Demo operations can resolve this from the controls below.</div>${B('Contact support','support','secondary full')}`;
const heading=t.status==='assigned'?'Meet your buddy.':t.status==='arrived'?'Jamie is at the meeting point.':t.status==='awaiting_end'?'You’ve arrived.':'Enjoy the way there.';
return `<div class="eyebrow">${t.status==='active'?'JOURNEY IN PROGRESS':t.status==='awaiting_end'?'FINAL CHECK-IN':'YOU’RE MATCHED'}</div><h1>${heading}</h1><p class="subheading">${t.status==='assigned'?'Head to the public meeting point when you’re ready.':t.status==='arrived'?'Say hello, then compare your meeting PIN.':t.status==='awaiting_end'?'Waiting for your buddy to confirm completion.':'A little conversation. One less solo journey.'}</p>${t.status==='active'?`<div class="detail-row"><span>To ${esc(P(t.to).name)}</span><b>${Math.max(0,q.minutes-Math.round(q.minutes*(t.milestone||0)/3))} min left</b></div><div class="tracking-bar"><span style="width:${Math.max(5,(t.milestone||0)/3*100)}%"></span></div><p class="microcopy" style="text-align:left">${state.flags.gps?'Simulated progress · Last check-in '+fmtTime(t.events.at(-1).at):'Location unavailable · Manual check-ins still work'}</p><div class="milestones">${['Meet at '+P(t.from).name,t.service==='subway'?'Enter station with your buddy':'Set off together',t.service==='subway'?'Ride together · confirm the exit':'Halfway through the neighborhood','Arrive at '+P(t.to).name].map((n,i)=>`<div class="milestone ${i<=(t.milestone||0)?'done':''} ${i===(t.milestone||0)+1?'active':''}"><span class="point">${i<=(t.milestone||0)?'✓':i+1}</span><div><h4>${esc(n)}</h4><p>${i===0?'Meeting PIN confirmed':i===3?'Finish at your agreed public destination':i<=(t.milestone||0)?'Checked in':'Upcoming checkpoint'}</p></div></div>`).join('')}</div><div class="button-row">${B(I('chat')+' Message','chat','secondary')}${B(I('share')+' Trip details','share','outline')}</div>${B('We’ve arrived','finish','primary full','style="margin-top:12px"')}${t.service==='subway'?B('Review route change','reroute','text full'):''}`:`${companion()}<div class="detail-row"><div>${I('pin')}<span><b>${esc(P(t.status==='awaiting_end'?t.to:t.from).name)}</b><small>${esc(P(t.status==='awaiting_end'?t.to:t.from).meet)}</small></span></div></div>${t.status!=='awaiting_end'?`<div style="margin-top:22px;text-align:center"><h3 style="font-size:12px">Your meeting PIN</h3><div class="meet-code">${t.code.split('').map(x=>`<span>${x}</span>`).join('')}</div><p class="microcopy">Share this with Jamie when you meet in person.</p></div>${t.status==='arrived'?B('I’ve met Jamie · Verify PIN','verify','primary full','style="margin-top:20px"'):`<div class="info-note">${I('clock')}Demo arrival: use “Companion arrives” below to move to the meeting step.</div>`}`:`<div class="info-note">${I('check')}Your completion is recorded. Use Demo controls to confirm as the companion, or try a completion disagreement.</div>${B('Review completion issue','disagreement','outline full')}`}`}${['assigned','arrived'].includes(t.status)?B('Cancel journey','cancel','text full'):''}<button class="safety-button" data-action="trip-safety">${I('shield')} Safety tools & support</button>`}
function completed(t){return `<div class="success-icon">${I('check')}</div><div class="center"><div class="eyebrow">A GOOD WALK, TOGETHER</div><h1>You’re here.</h1><p class="subheading">Thanks for walking with Jamie.</p></div><div class="detail-row"><span>${serviceName(t.service)}<small>${P(t.from).name} → ${P(t.to).name}</small></span><b>${money(t.quote.total+(t.tip||0))}</b></div><div style="text-align:center;margin-top:24px"><h3>How was your journey?</h3><p class="muted" style="font-size:11px">Your feedback helps shape the neighborhood.</p></div><div class="stars" role="group" aria-label="Rate your journey">${[1,2,3,4,5].map(n=>`<button data-action="rate" data-rating="${n}" class="${n<=(t.rating||0)?'chosen':''}" aria-label="${n} star${n>1?'s':''}" aria-pressed="${n===t.rating}">★</button>`).join('')}</div><div class="separator"></div><h3 style="font-size:12px">A little extra for Jamie?</h3><p class="muted" style="font-size:10px">100% of your tip would go to your companion.</p><div class="tip-buttons">${[0,2,4,6].map(n=>`<button data-action="tip" data-tip="${n}" class="${(t.tip||0)===n?'selected':''}">${n?money(n):'No tip'}</button>`).join('')}</div><p class="microcopy">Demo total only. No payment is collected.</p>${B('Done '+I('arrow'),'finish-feedback','primary full','style="margin-top:20px"')}${B(I('receipt')+' View receipt','receipt','text full',`data-id="${t.id}"`)}`}
function activity(){const items=state.trips.filter(t=>filter==='all'||(filter==='upcoming'?!M.terminal.includes(t.status):M.terminal.includes(t.status)));return `<div class="body-page"><div class="page-heading"><div><div class="eyebrow">YOUR WALK BUDDY JOURNAL</div><h1>Your journeys.</h1><p>The places you’re going. The company along the way.</p></div>${B(I('plus')+' Book a journey','nav','primary','data-view="book"')}</div><div class="page-grid"><div><div class="filter-tabs" role="group" aria-label="Filter journeys">${[['all','All journeys'],['upcoming','Upcoming'],['past','Past']].map(([f,n])=>`<button data-action="filter" data-filter="${f}" class="${filter===f?'active':''}">${n}</button>`).join('')}</div><div class="card">${items.length?items.map(t=>`<button class="journey-row" data-action="journey-detail" data-id="${t.id}"><span class="icon-box">${I(t.service==='walk'?'walk':'train')}</span><span><h3>${P(t.to).name}</h3><p>${fmtDate(t.date)} · ${fmtTime(t.date)}</p><span class="pill ${t.status==='cancelled'?'badge-warning':''}">${esc(t.status.replaceAll('_',' '))}</span>${t.sample?'<small class="muted" style="margin-left:7px">Sample history</small>':''}</span><span class="amount">${money(['cancelled','unavailable'].includes(t.status)?0:t.quote.total+(t.tip||0))}<small>${serviceName(t.service)}</small></span>${I('chevron')}</button>`).join(''):`<div class="empty-state">${I('calendar')}<h3>No journeys here yet.</h3><p>Your next walk is a good place to start.</p>${B('Plan a journey','nav','primary','data-view="book"')}</div>`}</div></div><div><div class="card"><h2>Your neighborhood, on foot.</h2><p class="muted" style="font-size:12px">Small journeys add up to a more familiar city.</p><div class="detail-row"><span>Completed journeys</span><b>${state.trips.filter(t=>t.status==='completed').length}</b></div><div class="detail-row"><span>Miles together</span><b>${state.trips.filter(t=>t.status==='completed').reduce((n,t)=>n+t.quote.miles,0).toFixed(1)}</b></div><p class="microcopy" style="text-align:left">Includes sample demo history.</p></div><div class="card"><h3>Need help with a journey?</h3><p class="muted" style="font-size:11px">Open a receipt or tell us what didn’t go as planned.</p>${B('Visit help center '+I('arrow'),'nav','text','data-view="help"')}</div></div></div></div>`}
function account(){return `<div class="body-page"><div class="page-heading"><div><div class="eyebrow">YOUR SPACE</div><h1>Account & preferences.</h1><p>A few details to make every journey feel more like you.</p></div></div><div class="page-grid"><div><section class="card"><div class="companion-head" style="margin-bottom:22px"><span class="avatar big">${esc(state.user.name.split(' ').map(n=>n[0]).slice(0,2).join(''))}</span><div><h2>${esc(state.user.name)}</h2><p>Personal account · Demo profile</p></div></div><form id="profile-form"><div class="form-grid"><label class="form-label">Full name<input name="name" value="${esc(state.user.name)}" required maxlength="80"></label><label class="form-label">Email<input name="email" type="email" value="${esc(state.user.email)}" required></label></div><label class="form-label">Default note for your companion<textarea name="notes" maxlength="300" placeholder="I’m new to the neighborhood…">${esc(state.user.notes)}</textarea></label><button class="btn primary">Save changes</button></form></section><section class="card"><h2>Journey preferences</h2><div class="setting-row"><div><h3>A quieter journey</h3><p>Let your buddy know you’re happy to walk without much conversation.</p></div><input class="switch" type="checkbox" data-setting="quiet" aria-label="Prefer a quiet journey" ${state.user.quiet?'checked':''}></div><div class="setting-row"><div><h3>Journey notifications</h3><p>Save your preference for trip updates. No push messages are sent in the demo.</p></div><input class="switch" type="checkbox" data-setting="notifications" aria-label="Journey notifications" ${state.user.notifications?'checked':''}></div></section><section class="card"><h2>Blocked companions</h2>${state.blocked.length?`<div class="detail-row"><span>Jamie L.<small>Excluded from future demo matches</small></span><button data-action="unblock">Unblock</button></div>`:'<p class="muted" style="font-size:11px">You haven’t blocked anyone.</p>'}</section><section class="card"><h2>Your data</h2><p class="muted" style="font-size:11px">Demo records are stored in this browser. They are not synced to a live marketplace.</p><div class="button-row">${B(I('download')+' Export my data','export','outline')}${B('Reset demo data','reset','outline')}</div></section></div><div><section class="card"><div class="section-label">Payment methods <button data-action="payment">Manage</button></div><div class="wallet-card"><div class="section-label"><span>${state.wallet.find(w=>w.id===state.payment).name.toUpperCase()}</span>${I('credit')}</div><div class="card-digits">•••• &nbsp; •••• &nbsp; ${state.wallet.find(w=>w.id===state.payment).last4}</div><small>TEST CARD · NO REAL CHARGES</small></div></section><section class="card"><div class="section-label">Saved places <button data-action="saved">Edit</button></div>${[['home','Home','home'],['work','Campus','work']].map(([key,label,ico])=>`<div class="detail-row"><div>${I(ico)}<span>${label}<small>${P(state.saved[key])?.name||'Not set'}</small></span></div></div>`).join('')}</section><section class="card"><div class="section-label">Trusted contacts <button data-action="contacts">Manage</button></div><p class="muted" style="font-size:11px">${state.contacts.length?state.contacts.map(c=>esc(c.name)).join(', '):'Add someone you’d like to keep in the loop.'}</p>${B(I('plus')+' Add a contact','contacts','secondary full')}</section></div></div></div>`}
function help(){return `<div class="body-page"><div class="page-heading"><div><div class="eyebrow">WE’RE HERE FOR THE JOURNEY</div><h1>How can we help?</h1><p>Answers, safety tools, and a way to tell us what happened.</p></div></div><div class="page-grid"><div><section class="card"><h2>Good to know before you go</h2><div class="faq">${[['What does my buddy help with?','Your buddy offers company and practical navigation from an agreed public meeting point to your destination. Subway Together includes station entry, platforms, transfers, and your final exit. This is not security, caregiving, or emergency response.'],['How do I recognize my companion?','Check the profile, meet in the agreed public place, and compare the four-digit meeting PIN. If the PIN does not match or something feels wrong, do not start the journey.'],['Can I cancel my journey?','In this demo, you can cancel any time before starting without a fee. A production cancellation policy has not been finalized. Once a journey has started, you can end it immediately through Safety tools.'],['Is subway fare included?','No. Each person pays their own transit fare. The quoted amount covers companionship and navigation. The preview route and duration are estimates, not live MTA information.'],['Can I keep my home address private?','Yes. Use a nearby public meeting and drop-off point. The demo uses a curated list of public places in the East Village and NYU pilot area.'],['Is this a live service?','This is an interactive product demo with fictional profiles, sample prices, and simulated trip states. No real companion, payment, support team, or live location is connected.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div></section><section class="card"><h2>Your support requests</h2>${state.reports.length?state.reports.map(r=>`<button class="selection-row" data-action="case" data-id="${r.id}">${I('flag')}<span><h3>${esc(r.subject)}</h3><p>${r.id} · ${r.resolved?'Reviewed':'Saved locally'} · ${fmtDate(r.at)}</p></span>${I('chevron')}</button>`).join(''):'<p class="muted" style="font-size:12px">No support requests yet.</p>'}</section></div><div><section class="card"><div class="icon-box" style="margin-bottom:16px">${I('shield')}</div><h2>Your comfort comes first.</h2><p class="muted" style="font-size:12px">You can end a journey at any time. You never need to stay in an uncomfortable situation.</p>${B('Open safety tools','trip-safety','secondary full')}</section><section class="card"><h3>Something else?</h3><p class="muted" style="font-size:11px">Save a support request in this demo.</p>${B(I('chat')+' Contact support','support','outline full')}</section></div></div></div>`}
function workspace(){const completed=state.trips.filter(t=>t.status==='completed'&&!t.sample),open=state.trips.filter(t=>!M.terminal.includes(t.status));return `<div class="body-page"><div class="page-heading"><div><div class="eyebrow">${view==='companion'?'COMPANION WORKSPACE':'OPERATIONS WORKSPACE'} · DEMO</div><h1>${view==='companion'?'Good company starts with you.':'Keep the neighborhood moving.'}</h1><p>${view==='companion'?'Your offers, availability, and earnings in one place.':'Local demo records. No production accounts or live dispatch.'}</p></div>${B('Rider view '+I('arrow'),'nav','outline','data-view="book"')}</div><div class="progress-stats"><div class="stat"><strong>${open.length}</strong><small>Open journeys</small></div><div class="stat"><strong>${completed.length}</strong><small>Completed demos</small></div><div class="stat"><strong>${view==='companion'?money(completed.reduce((a,t)=>a+t.quote.total*.75+(t.tip||0),0)):state.reports.filter(r=>!r.resolved).length}</strong><small>${view==='companion'?'Sample net earnings':'Unreviewed cases'}</small></div></div><div class="page-grid"><div><section class="card"><h2>${view==='companion'?'Your journey offers':'Journey board'}</h2>${open.length?open.map(t=>`<div class="journey-row"><span class="icon-box">${I(t.service==='walk'?'walk':'train')}</span><div><h3>${P(t.from).name} → ${P(t.to).name}</h3><p>${serviceName(t.service)} · ${fmtTime(t.date)} · ${t.status.replaceAll('_',' ')}</p><small class="muted">${view==='companion'?'Estimated earnings '+money(t.quote.total*.75):t.id}</small></div><div style="margin-left:auto">${B(t.status==='searching'?'Accept offer':'Open journey','workspace-open','primary',`data-id="${t.id}"`)}</div></div>`).join(''):'<div class="empty-state"><h3>No open journeys.</h3><p>Create one in the rider view to explore the full workflow.</p></div>'}</section>${view==='ops'?`<section class="card"><h2>Incident & support queue</h2>${state.reports.map(r=>`<div class="detail-row"><span><b>${esc(r.subject)}</b><small>${r.id} · ${esc(r.reason||'General support')}</small></span>${B(r.resolved?'Reviewed':'Review','case','outline',`data-id="${r.id}"`)}</div>`).join('')||'<p class="muted" style="font-size:12px">No local cases.</p>'}</section>`:''}</div><div><section class="card"><h2>${view==='companion'?'Availability':'Pilot controls'}</h2>${view==='companion'?`<div class="setting-row"><div><h3>Available for offers</h3><p>East Village / NYU</p></div><input type="checkbox" class="switch" data-flag="availability" aria-label="Available for demo offers" ${state.availability?'checked':''}></div><div class="info-note">${I('shield')}Jamie L. is a fictional, pre-approved profile for this demo. Live approval, screening, and payouts are not connected.</div>`:`<div class="setting-row"><div><h3>Pause new requests</h3><p>Existing journeys remain accessible.</p></div><input type="checkbox" class="switch" data-flag="paused" aria-label="Pause new requests" ${state.flags.paused?'checked':''}></div><div class="setting-row"><div><h3>Companion supply</h3><p>Turn off to demonstrate no availability.</p></div><input type="checkbox" class="switch" data-flag="supply" aria-label="Enable companion supply" ${state.flags.supply?'checked':''}></div>`}</section><section class="card"><h2>Latest events</h2>${state.trips.flatMap(t=>t.events.slice(-2).map(e=>({...e,id:t.id}))).sort((a,b)=>b.at.localeCompare(a.at)).slice(0,5).map(e=>`<div class="detail-row"><span>${esc(e.type)}<small>${e.id} · ${fmtTime(e.at)}</small></span></div>`).join('')}</section></div></div></div>`}
function render(){const scroll=$('.panel-scroll')?.scrollTop||0;$('#app').innerHTML=header()+(view==='book'?`<div class="app-layout"><section class="booking-panel" aria-label="Journey booking"><div class="panel-scroll">${({plan,options,review,trip:tripView}[step]||plan)()}</div>${step==='trip'?'':`<div class="panel-footer">${I('shield')}Public meeting points. Personal space. Your pace.</div>`}</section>${mapMarkup()}</div>`:view==='activity'?activity():view==='account'?account():view==='help'?help():workspace())+dock();if($('.panel-scroll')&&step==='trip')$('.panel-scroll').scrollTop=scroll;persist();if(step==='trip'&&current()?.status==='searching')scheduleMatch()}
function navigate(v){view=v;if(v==='book'){const t=active();if(t){state.currentId=t.id;step='trip'}else if(step==='trip')step='plan'}render();window.scrollTo(0,0)}
function scheduleMatch(){clearTimeout(searchTimer);const id=current()?.id;searchTimer=setTimeout(()=>{const t=state.trips.find(x=>x.id===id);if(t?.status==='searching'){M.transition(t,state.flags.supply&&!state.blocked.includes('jamie')?'assigned':'unavailable');persist();render()}},4500)}
function showSuggestions(field,term=''){const el=$('#suggest-'+field);if(!el)return;const matches=M.places.filter(p=>(p.name+' '+p.address+' '+p.area).toLowerCase().includes(term.toLowerCase())).slice(0,6);el.innerHTML=matches.length?matches.map(p=>`<button type="button" data-action="choose-place" data-field="${field}" data-place="${p.id}">${I(p.id==='astor'?'train':'pin')}<span><b>${p.name}</b><small>${p.address}</small></span></button>`).join(''):`<div class="no-result">We’re starting small.<br>Choose a public place in our East Village / NYU pilot area. Try “Union Square” or “Astor Place.”</div>`;el.hidden=false}
function scheduleDialog(){const d=draft.date?new Date(draft.date):new Date(Date.now()+3600e3);const local=new Date(d-d.getTimezoneOffset()*6e4).toISOString().slice(0,16);modal('When are we heading out?',`<p>Choose a departure time for your journey.</p><form id="schedule-form"><label class="radio-label"><input name="when" type="radio" value="now" ${draft.when==='now'?'checked':''}>Leave now <span class="pill" style="margin-left:auto">Demo preview</span></label><label class="radio-label" style="margin-top:10px"><input name="when" type="radio" value="later" ${draft.when==='later'?'checked':''}>Schedule for later</label><label class="form-label">Departure date & time<input type="datetime-local" name="date" value="${local}"></label><p class="microcopy" style="text-align:left">Times use your device’s local timezone. Scheduled demo trips can be advanced immediately for a presentation.</p><p class="inline-error" id="schedule-error"></p><button class="btn primary full" style="margin-top:18px">Set departure time</button></form>`)}
function paymentDialog(){modal('Choose a payment method',`<p>Use a test card for this demo. No real card details are needed.</p>${state.wallet.map(w=>`<button class="selection-row ${state.payment===w.id?'selected':''}" data-action="select-payment" data-payment="${w.id}"><span class="card-number">${w.name==='Visa'?'VISA':'MC'}</span><span><h3>${w.name} •••• ${w.last4}</h3><p>Expires ${w.expiry} · Test card</p></span>${I(state.payment===w.id?'check':'chevron')}</button>`).join('')}<div class="info-note">${I('lock')}A production payment processor is not connected. Both payment options are simulated.</div>`)}
function fareDialog(t){const q=t?.quote||M.quote(draft.from,draft.to,draft.service);modal('A clear price, upfront',`<p>${serviceName(t?.service||draft.service)} · ${q.minutes} min · ${q.miles} mi</p><div class="detail-row"><span>Base companionship</span><b>${money(q.base)}</b></div><div class="detail-row"><span>Estimated journey time</span><b>${money(q.time)}</b></div><div class="detail-row"><span>Service fee</span><b>${money(q.fee)}</b></div><div class="total-row"><span>Total estimate</span><b>${money(q.total)}</b></div><p>Sample rate card for the demo. Any material route or price change requires your agreement. Subway fares are separate.</p>`)}
function receiptDialog(id){const t=state.trips.find(x=>x.id===id)||current();if(!t)return;modal('Journey receipt',`<div class="receipt-brand">kyn<span style="font-size:10px;margin-left:6px">NYC</span></div><div class="receipt-meta">${t.id} · ${fmtDate(t.date)} at ${fmtTime(t.date)}</div><div class="receipt-total">${money(t.quote.total+(t.tip||0))}</div><p class="muted" style="font-size:11px">Demo receipt · Actual charged amount: $0.00</p>${routeSummary(t.from,t.to)}<div class="detail-row"><span>${serviceName(t.service)}</span><b>${money(t.quote.base+t.quote.time)}</b></div><div class="detail-row"><span>Service fee</span><b>${money(t.quote.fee)}</b></div><div class="detail-row"><span>Tip to Jamie</span><b>${money(t.tip||0)}</b></div><div class="detail-row"><span>Payment method</span><span>${state.wallet.find(w=>w.id===t.payment)?.name||'Test card'} •••• ${state.wallet.find(w=>w.id===t.payment)?.last4||'4242'}</span></div><div class="detail-row"><span>Your rating</span><span>${t.rating?'★ '+t.rating+' / 5':'Not rated'}</span></div>${B(I('download')+' Download receipt','download-receipt','primary full',`data-id="${t.id}" style="margin-top:20px"`)}${B('Get help with this journey','support','text full',`data-id="${t.id}"`)}`)}
function download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function chatDialog(){const t=current();if(!t)return;modal('Message Jamie',`<p>Fictional companion · Demo conversation</p><div class="chat-log">${t.messages.map(m=>`<div class="message ${m.who==='me'?'mine':''}">${esc(m.text)}<small>${m.who==='me'?'You':'Jamie'} · ${fmtTime(m.at)}</small></div>`).join('')}</div><div class="quick-replies">${['I’m at the entrance.','I’m running 2 minutes late.','What are you wearing?'].map(m=>`<button data-action="quick-message" data-message="${esc(m)}">${m}</button>`).join('')}</div><form id="chat-form" class="chat-input"><input name="message" required maxlength="500" placeholder="Message your buddy…" aria-label="Message to Jamie"><button class="btn primary" aria-label="Send demo message">${I('arrow')}</button></form>`);const log=$('.chat-log');log.scrollTop=log.scrollHeight}
function sendMessage(text){const t=current();if(!t||!text.trim())return;t.messages.push({who:'me',text:text.trim(),at:new Date().toISOString()});const response=text.toLowerCase().includes('wear')?'Green jacket, black backpack. See you by the entrance!':text.toLowerCase().includes('late')?'No problem. I’ll wait at the meeting point. Thanks for the heads-up!':'Got it! I’m by the public entrance. We’ll compare the PIN when we meet.';t.messages.push({who:'companion',text:response,at:new Date().toISOString()});persist();chatDialog()}
function safetyDialog(){const t=current();modal('Your safety tools',`<p>You’re in control of your journey. You can leave at any time.</p><a class="selection-row" href="tel:911" style="text-decoration:none">${I('phone')}<span><h3>Call 911</h3><p>For an immediate emergency</p></span>${I('chevron')}</a>${t&&!M.terminal.includes(t.status)?`<button class="selection-row" data-action="report">${I('flag')}<span><h3>End journey & report</h3><p>Leave the journey immediately</p></span>${I('chevron')}</button><button class="selection-row" data-action="share">${I('share')}<span><h3>View trip sharing</h3><p>Control this session’s sharing preference</p></span>${I('chevron')}</button>`:''}<button class="selection-row" data-action="support">${I('chat')}<span><h3>Contact support</h3><p>Create a local support request</p></span>${I('chevron')}</button><div class="info-note">${I('info')}This demo does not monitor journeys or notify a support team. Use your phone directly for urgent help.</div>`)}
function shareDialog(){const t=current();modal('Keep someone in the loop',`<p>Share a summary with someone you trust. Live location sharing is not connected in this demo.</p>${routeSummary(t.from,t.to)}<div class="detail-row"><span>Companion</span><b>Jamie L. · Fictional profile</b></div><div class="detail-row"><span>Journey</span><span>${t.id}</span></div><div class="setting-row"><div><h3>Trip sharing preference</h3><p>${t.share?'Enabled for this demo session':'Off for this session'} · Stops when the journey ends</p></div><input type="checkbox" class="switch" data-share="true" aria-label="Trip sharing preference" ${t.share?'checked':''} ${M.terminal.includes(t.status)?'disabled':''}></div>${B(I('download')+' Download trip summary','download-summary','outline full','style="margin-top:16px"')}<p class="microcopy">The file is a static summary. It does not track your location.</p>`)}
function cancelDialog(){modal('Cancel this journey?',`<p>Your buddy won’t meet you once the journey is cancelled. No fee applies in this demo.</p><form id="cancel-form"><div class="report-list">${['My plans changed','The meeting point isn’t right','The wait is too long','Something else'].map((r,i)=>`<label class="radio-label"><input type="radio" name="reason" value="${r}" ${i===0?'checked':''}>${r}</label>`).join('')}</div><div class="button-row"><button type="button" class="btn secondary" data-action="close">Keep journey</button><button class="btn primary">Confirm cancellation</button></div></form>`)}
function reportDialog(){const t=current();if(t&&!M.terminal.includes(t.status)){if(t.status==='searching'){closeModal();cancelDialog();return}M.transition(t,'reported');persist();render()}modal('Journey ended. Tell us what happened.',`<p>You are no longer in an active journey. Details are optional. No support team is notified by this demo.</p><form id="report-form"><label class="form-label">Reason<select name="reason"><option>I felt uncomfortable</option><option>Wrong person or PIN</option><option>Route or destination problem</option><option>Other concern</option></select></label><label class="form-label">Anything else? (optional)<textarea name="details" maxlength="2000" placeholder="Share only what you’re comfortable sharing."></textarea></label><label class="check-label"><input type="checkbox" name="block">Block Jamie from future demo matches</label><button class="btn primary full">Save report</button></form>`)}
function supportDialog(id){modal('Tell us how we can help',`<p>This creates a support case in the local demo, with a reference number you can review in Help.</p><form id="support-form"><input type="hidden" name="tripId" value="${esc(id||current()?.id||'')}"><label class="form-label">Topic<select name="subject"><option>A question about my journey</option> <option>Payment or receipt</option><option>Accessibility and assistance</option><option>Account and privacy</option><option>Other</option></select></label><label class="form-label">Your message<textarea name="details" required maxlength="2000" placeholder="Tell us a little more…"></textarea></label><button class="btn primary full">Save support request</button></form>`)}
function savedDialog(){modal('Your saved places',`<p>Use public destinations to keep your exact home address private.</p><form id="saved-form">${[['home','Home'],['work','Campus / work']].map(([key,label])=>`<label class="form-label">${label}<select name="${key}">${M.places.map(p=>`<option value="${p.id}" ${state.saved[key]===p.id?'selected':''}>${p.name}</option>`).join('')}</select></label>`).join('')}<button class="btn primary full">Save places</button></form>`)}
function contactsDialog(){modal('Trusted contacts',`<p>Contacts are saved on this device. No invitations or text messages are sent.</p>${state.contacts.map((c,i)=>`<div class="detail-row"><span><b>${esc(c.name)}</b><small>${esc(c.phone)}</small></span><button data-action="remove-contact" data-index="${i}">Remove</button></div>`).join('')}<form id="contacts-form"><label class="form-label">Name<input name="name" required maxlength="60" placeholder="A friend or family member"></label><label class="form-label">Phone number<input name="phone" required type="tel" maxlength="24" placeholder="(212) 555-0123"></label><button class="btn primary full">Add contact</button></form>`)}
function demoDialog(){modal('Run the demo your way',`<p>All people, prices, and trip updates are simulated. The customer interface behaves like a real booking flow; these controls let you play the other side.</p><div class="demo-grid">${[['walk','walkthrough','Walk Home','Start with a prefilled neighborhood walk.'],['train','subway-demo','Subway Together','Try a guided station-to-station journey.'],['users','no-supply','No availability','Show a graceful no-charge fallback.'],['locate','gps-demo','Location loss','Toggle location status during a trip.'],['user','companion-view','Companion view','Availability, offers, and earnings.'],['settings','ops-view','Operations view','Requests, pilot pause, and reports.']].map(([i,a,title,desc])=>`<button class="demo-option" data-action="${a}">${I(i)}<h3>${title}</h3><p>${desc}</p></button>`).join('')}</div><div class="info-note">${I('info')}Fast demo: choose a route → confirm → use the bottom bar to advance arrival and checkpoints → finish → rate and view the receipt.</div><div class="button-row">${B('Reset sample data','reset','outline')}${B('Continue exploring','close','primary')}</div>`)}
function caseDialog(id){const r=state.reports.find(x=>x.id===id)||state.reports.at(-1);if(!r)return modal('No report saved yet',`<p>Your journey is ended. You can still add a report.</p>${B('Add report','report','primary full')}`);modal('Support request '+r.id,`<span class="pill">${r.resolved?'Reviewed locally':'Saved locally'}</span><h3 style="margin-top:20px">${esc(r.subject)}</h3><p>${esc(r.details||'No details provided.')}</p><div class="detail-row"><span>Created</span><span>${fmtDate(r.at)} · ${fmtTime(r.at)}</span></div>${r.reason?`<div class="detail-row"><span>Reason</span><span>${esc(r.reason)}</span></div>`:''}<div class="info-note">${I('info')}This case exists only in this browser. It has not been delivered to a live support team.</div>${view==='ops'&&!r.resolved?B('Mark reviewed with a note','resolve-case','primary full',`data-id="${r.id}"`):''}`)}
function startScenario(service='walk',noSupply=false){if(active()){closeModal();navigate('book');return toast('Finish the current journey first, or use the restart control.')}draft={from:'union',to:service==='subway'?'astor':'washington',service,when:'now',date:'',notes:''};state.currentId=null;state.flags.supply=!noSupply;state.flags.paused=false;view='book';step='plan';closeModal();render();toast(noSupply?'No-availability scenario loaded. Continue booking.':'Demo route is ready. Continue with “See available journeys.”')}
function advance(){const t=current();if(!t)return;try{if(t.status==='searching'){clearTimeout(searchTimer);M.transition(t,state.flags.supply&&!state.blocked.includes('jamie')?'assigned':'unavailable')}else if(t.status==='assigned')M.transition(t,'arrived');else if(t.status==='arrived'){toast('Demo companion PIN: '+t.code+'. Use “Verify PIN” to begin.');return}else if(t.status==='active'){if(t.milestone>=3)M.finish(t);else M.nextMilestone(t)}else if(t.status==='awaiting_end'||t.status==='review')M.transition(t,'completed');persist();render()}catch(e){alertError(e)}}
const actions={
nav:el=>{closeModal();navigate(el.dataset.view)},close:closeModal,
service:el=>{draft.service=el.dataset.service;render()},
'choose-place':el=>{draft[el.dataset.field]=el.dataset.place;render();if(el.dataset.field==='from')$('#to')?.focus()},
'clear-place':el=>{draft[el.dataset.field]='';render();$('#'+el.dataset.field)?.focus()},
swap:()=>{[draft.from,draft.to]=[draft.to,draft.from];render()},
'saved-go':el=>{draft.to=state.saved[el.dataset.place];render()},saved:savedDialog,
schedule:scheduleDialog,option:el=>{draft.service=el.dataset.service;render()},
'back-plan':()=>{step='plan';render()},'back-options':()=>{step='options';render()},review:()=>{step='review';render()},
request:()=>{try{if($('#adult')){if(!$('#adult').checked)throw Error('Please confirm that you’re 18 or older to continue.');state.user.ageConfirmed=true}const t=M.create(state,draft);state.currentId=t.id;step='trip';render()}catch(e){$('#review-error').textContent=e.message}},
payment:paymentDialog,'select-payment':el=>{state.payment=el.dataset.payment;persist();closeModal();render();toast('Payment method updated')},fare:()=>fareDialog(),
notes:()=>modal('A note for your buddy',`<p>Keep it simple. Let your companion know how to make the journey more comfortable.</p><form id="notes-form"><label class="form-label">Your note<textarea name="notes" maxlength="300" placeholder="I’m new to the subway. Could you explain the platform signs?">${esc(draft.notes||state.user.notes)}</textarea></label><button class="btn primary full">Save note</button></form>`),
'cancellation-policy':()=>modal('Cancellation, without surprises',`<p>Cancel before the journey starts with no fee in this demo. Your request is closed and no payment is taken.</p><p>After starting, Safety tools lets you end a journey immediately. A production cancellation and refund policy remains to be finalized.</p>`),
coverage:()=>modal('Starting with one neighborhood',`<p>The pilot covers public meeting points around East Village, NYU, and Union Square.</p>${M.places.map(p=>`<div class="detail-row"><span>${p.name}<small>${p.area}</small></span>${I('pin')}</div>`).join('')}<p class="microcopy">Map boundaries and routes are illustrative. No live navigation provider is connected.</p>`),
'zoom-in':()=>{zoom=Math.min(1.65,zoom+.15);$('.map-canvas').style.transform=`scale(${zoom})`},'zoom-out':()=>{zoom=Math.max(.85,zoom-.15);$('.map-canvas').style.transform=`scale(${zoom})`},recenter:()=>{zoom=1;$('.map-canvas').style.transform='scale(1)'},
advance,chat:chatDialog,'quick-message':el=>sendMessage(el.dataset.message),
'companion-profile':()=>modal('Meet Jamie L.',`<div class="companion-head"><span class="avatar big person">JL</span><div><h2>Jamie L.</h2><p>East Village · Member since 2025</p></div></div><div class="detail-row"><span>Rating</span><b>★ 4.96 · 128 journeys</b></div><div class="detail-row"><span>Languages</span><span>English, Spanish</span></div><div class="detail-row"><span>Services</span><span>Walk Home · Subway Together</span></div><h3 style="margin-top:22px">A little about me</h3><p>NYU alum, weekend photographer, and a big fan of the quiet streets around Washington Square. Happy to chat or just keep you company.</p><h3>Before joining</h3><ul class="checklist"><li>${I('check')} Identity and background review</li><li>${I('check')} Companion conduct training</li><li>${I('check')} Subway navigation orientation</li></ul><div class="info-note">${I('info')}This profile, rating, and screening history are fictional demo data. No real person has been screened or assigned.</div>`),
verify:()=>modal('A quick hello. A matching PIN.',`<p>In a live journey, your buddy would compare the PIN with you. For this demo, enter the four digits shown on your journey screen.</p><form id="verify-form"><label class="form-label">Companion’s matching PIN<input name="pin" inputmode="numeric" pattern="[0-9]{4}" minlength="4" maxlength="4" required autocomplete="off" placeholder="4-digit PIN" autofocus></label><p class="inline-error" id="verify-error" aria-live="polite"></p><button class="btn primary full">Verify & start journey</button></form><button class="btn text full" data-action="report">Something doesn’t feel right</button>`),
finish:()=>{try{M.finish(current());render()}catch(e){alertError(e)}},
disagreement:()=>{M.transition(current(),'review');render();toast('Placed in completion review. No additional charge.')},
rate:el=>{current().rating=Number(el.dataset.rating);render()},tip:el=>{current().tip=Number(el.dataset.tip);render()},
'finish-feedback':()=>{toast('Thanks for sharing your feedback.');navigate('activity')},
receipt:el=>receiptDialog(el.dataset.id),
'download-receipt':el=>{const t=state.trips.find(x=>x.id===el.dataset.id)||current();download(t.id+'-receipt.txt',`WALKBUDDY NYC — DEMO RECEIPT\n${t.id}\n${fmtDate(t.date)} ${fmtTime(t.date)}\n\n${serviceName(t.service)}\nFrom: ${P(t.from).name}\nTo: ${P(t.to).name}\nCompanion: Jamie L. (fictional)\n\nCompanionship: ${money(t.quote.base+t.quote.time)}\nService fee: ${money(t.quote.fee)}\nTip: ${money(t.tip||0)}\nDemo total: ${money(t.quote.total+(t.tip||0))}\nACTUAL CHARGED: $0.00\n\nThis is a simulated receipt. No service or payment was fulfilled.`);toast('Receipt downloaded')},
share:shareDialog,'download-summary':()=>{const t=current();download(t.id+'-journey.txt',`KYN — static demo journey summary\n${t.id}\nFrom: ${P(t.from).name}\nTo: ${P(t.to).name}\nDeparture: ${fmtDate(t.date)} ${fmtTime(t.date)}\nCompanion: Jamie L. (fictional)\nStatus at export: ${t.status}\n\nThis document does not update or share live location.`);toast('Trip summary downloaded')},
'new-journey':()=>{state.currentId=null;draft.to='';step='plan';view='book';render()},retry:()=>{const t=current();draft={from:t.from,to:t.to,service:t.service,when:'later',date:new Date(Date.now()+3600e3).toISOString(),notes:t.notes};state.currentId=null;state.flags.supply=true;step='plan';render();scheduleDialog()},cancel:cancelDialog,
'journey-detail':el=>{const t=state.trips.find(x=>x.id===el.dataset.id);state.currentId=t.id;if(t.status==='completed')receiptDialog(t.id);else{view='book';step='trip';render()}},filter:el=>{filter=el.dataset.filter;render()},
contacts:contactsDialog,'remove-contact':el=>{state.contacts.splice(Number(el.dataset.index),1);persist();contactsDialog()},
export:()=>{download('kyn-demo-data.json',JSON.stringify(state,null,2),'application/json');toast('Your local demo data was exported')},
reset:()=>modal('Reset the demo?',`<p>This clears journeys and preferences from this browser and restores the original sample history. You can export your data first from Account.</p><div class="button-row">${B('Keep my data','close','secondary')}${B('Reset sample data','confirm-reset','primary')}</div>`),
'confirm-reset':()=>{clearTimeout(searchTimer);state=M.seed();draft={from:'union',to:'',service:'walk',when:'now',date:'',notes:''};step='plan';view='book';closeModal();render();toast('Fresh demo ready')},
restart:()=>{if(active())modal('Start a fresh walkthrough?',`<p>The current demo journey will be marked as stopped. Your other journeys and preferences are kept.</p><div class="button-row">${B('Keep journey','close','secondary')}${B('Start again','confirm-restart','primary')}</div>`);else actions['confirm-restart']()},
'confirm-restart':()=>{clearTimeout(searchTimer);const t=active();if(t){t.status='cancelled';t.share=false;M.addEvent(t,'Stopped using demo controls')}state.currentId=null;draft={from:'union',to:'washington',service:'walk',when:'now',date:'',notes:''};view='book';step='plan';closeModal();render()},
unblock:()=>{state.blocked=[];persist();render();toast('Jamie can appear in demo matches again')},
itinerary:()=>{const t=step==='trip'?current():null,from=t?.from||draft.from,to=t?.to||draft.to;const direct=['union','astor'].includes(from)&&['union','astor'].includes(to)&&from!==to;modal('Your subway journey',`<p>${P(from).name} → ${P(to).name}</p>${direct?`<div class="milestones"><div class="milestone done"><span class="point">1</span><div><h4>Meet outside ${P(from).name}</h4><p>Compare your PIN before entering the station.</p></div></div><div class="milestone"><span class="subway-bullet">6</span><div><h4>${from==='union'?'Downtown toward Brooklyn Bridge–City Hall':'Uptown toward Pelham Bay Park'}</h4><p>Sample itinerary · one stop · ride together.</p></div></div><div class="milestone"><span class="point">3</span><div><h4>Exit at ${P(to).name}</h4><p>Your buddy stays with you through the agreed exit.</p></div></div></div>`:`<div class="info-note">${I('train')}This route needs companion review. The demo does not invent a train itinerary for this pair of meeting points. Try Union Square ↔ Astor Place for the detailed subway scenario.</div>`}<div class="detail-row"><span>Transit fare</span><span>Paid separately by each rider</span></div><p class="microcopy">Illustrative itinerary only. No live MTA schedules, closures, or accessibility data are connected.</p>`)},
'demo':demoDialog,walkthrough:()=>startScenario('walk'),'subway-demo':()=>startScenario('subway'),'no-supply':()=>startScenario('walk',true),
'gps-demo':()=>{state.flags.gps=!state.flags.gps;persist();closeModal();render();toast(state.flags.gps?'Simulated location restored':'Location unavailable scenario enabled')},
'companion-view':()=>{closeModal();navigate('companion')},'ops-view':()=>{closeModal();navigate('ops')},
'workspace-open':el=>{const t=state.trips.find(x=>x.id===el.dataset.id);if(t.status==='searching'){if(view==='companion'&&!state.availability)return toast('Turn on availability before accepting an offer.');if(!state.flags.supply)return toast('Demo companion supply is disabled.');M.transition(t,'assigned');clearTimeout(searchTimer)}state.currentId=t.id;view='book';step='trip';render()},
'support':el=>supportDialog(el?.dataset?.id),
'case':el=>caseDialog(el.dataset.id),'report-status':()=>caseDialog(),
'resolve-case':el=>modal('Record the review',`<form id="resolve-form"><input type="hidden" name="id" value="${el.dataset.id}"><label class="form-label">Review note<textarea name="note" required maxlength="1000" placeholder="Record the outcome and why."></textarea></label><button class="btn primary full">Save review</button></form>`),
report:reportDialog,'trip-safety':safetyDialog,
reroute:()=>modal('Review a route change',`<p>Jamie suggests using a different station entrance because the original entrance is unavailable.</p><div class="detail-row"><span>Destination</span><b>${P(current().to).name}</b></div><div class="detail-row"><span>Additional time</span><b>About 5 minutes</b></div><div class="detail-row"><span>Price change</span><b>$0.00</b></div><div class="info-note">${I('info')}This is a sample disruption, not a live service alert. Your buddy’s agreement is simulated after you approve.</div><div class="button-row">${B('Keep original plan','decline-route','secondary')}${B('Agree to change','approve-route','primary')}</div>`),
'approve-route':()=>{const t=current();t.routeChanged=true;M.addEvent(t,'Customer accepted sample entrance change; companion confirmed (demo)');persist();closeModal();render();toast('Route change agreed. Your price stays the same.')},
'decline-route':()=>{M.addEvent(current(),'Route change declined; original quote retained');persist();closeModal();toast('Original plan kept. No price change.')}
};
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el){e.preventDefault();try{actions[el.dataset.action]?.(el)}catch(err){alertError(err)}}else if(!e.target.closest('.input-wrap'))$$('.suggestions').forEach(s=>s.hidden=true)});
document.addEventListener('focusin',e=>{if(e.target.dataset.location)showSuggestions(e.target.dataset.location,'')});
document.addEventListener('input',e=>{if(e.target.dataset.location){draft[e.target.dataset.location]='';showSuggestions(e.target.dataset.location,e.target.value)}});
document.addEventListener('keydown',e=>{if(e.target.dataset.location&&e.key==='ArrowDown'){e.preventDefault();$('#suggest-'+e.target.dataset.location+' button')?.focus()}if(e.key==='Escape')$$('.suggestions').forEach(s=>s.hidden=true)});
document.addEventListener('change',e=>{if(e.target.dataset.setting){state.user[e.target.dataset.setting]=e.target.checked;persist();toast('Preference saved')}if(e.target.dataset.flag){if(e.target.dataset.flag==='availability')state.availability=e.target.checked;else state.flags[e.target.dataset.flag]=e.target.checked;state.audit.push({type:e.target.dataset.flag+' changed',at:new Date().toISOString()});persist();toast('Demo setting updated')}if(e.target.dataset.share){current().share=e.target.checked;persist();shareDialog()}});
document.addEventListener('submit',e=>{const form=e.target;if(!form.id)return;e.preventDefault();const d=Object.fromEntries(new FormData(form));try{
if(form.id==='planner'){try{if(active())throw Error('You already have a journey in progress. Open it from Activity.');M.quote(draft.from,draft.to,draft.service);step='options';render()}catch(err){$('#plan-error').textContent=err.message}}
else if(form.id==='schedule-form'){if(d.when==='later'&&new Date(d.date).getTime()<Date.now()+60e3){$('#schedule-error').textContent='Choose a time at least one minute from now.';return}if(d.when==='later'&&!d.date){$('#schedule-error').textContent='Choose a departure date and time.';return}draft.when=d.when;draft.date=d.when==='later'?new Date(d.date).toISOString():'';closeModal();render()}
else if(form.id==='notes-form'){draft.notes=d.notes.trim();closeModal();render()}
else if(form.id==='verify-form'){try{M.verify(current(),d.pin);closeModal();render();toast('PIN confirmed. Your journey has started.')}catch(err){$('#verify-error').textContent=err.message}}
else if(form.id==='chat-form')sendMessage(d.message);
else if(form.id==='cancel-form'){const t=current();M.transition(t,'cancelled');t.cancelReason=d.reason;clearTimeout(searchTimer);closeModal();render()}
else if(form.id==='profile-form'){state.user.name=d.name.trim()||'Alex Morgan';state.user.email=d.email.trim();state.user.notes=d.notes.trim();render();toast('Your profile has been updated')}
else if(form.id==='saved-form'){state.saved=d;closeModal();render();toast('Saved places updated')}
else if(form.id==='contacts-form'){state.contacts.push({name:d.name.trim(),phone:d.phone.trim()});persist();contactsDialog();toast('Contact saved on this device')}
else if(form.id==='free-form'){state.freeInterest={area:d.area,at:new Date().toISOString()};persist();modal('You’re on the demo list.',`<p>Your interest in walking around ${esc(d.area)} is saved on this device. In a live pilot, this would be followed by eligibility checks and an invitation.</p>${B('Back to exploring','close','primary full')}`)}
else if(form.id==='report-form'){const t=current();const r={id:'CASE-'+Date.now().toString(36).toUpperCase(),tripId:t?.id,subject:'Journey safety report',reason:d.reason,details:d.details,at:new Date().toISOString(),resolved:false};state.reports.push(r);if(d.block&&!state.blocked.includes('jamie'))state.blocked.push('jamie');persist();caseDialog(r.id)}
else if(form.id==='support-form'){const r={id:'CASE-'+Date.now().toString(36).toUpperCase(),...d,at:new Date().toISOString(),resolved:false};state.reports.push(r);persist();caseDialog(r.id)}
else if(form.id==='resolve-form'){const r=state.reports.find(x=>x.id===d.id);r.resolved=true;r.reviewNote=d.note;r.reviewedAt=new Date().toISOString();persist();closeModal();render();toast('Case reviewed with an audit note')}
}catch(err){alertError(err)}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal()});
if(active()){state.currentId=active().id;step='trip'}render();
